31	type Frame = {
32	  filename: string;
33	  lineno: number;
34	  name: string;
35	};
36	
37	type ErrorDetail = {
38	  exc_notes: Array<string>;
39	  exc_type: string;
40	  exc_value: string;
41	  frames: Array<Frame>;
42	  is_cause: boolean;
43	  syntax_error: string | null;
44	};
