19	import type { UseQueryOptions } from "@tanstack/react-query";
20	import dayjs from "dayjs";
21	import type { TFunction } from "i18next";
22	import type { JSX } from "react";
23	import { useTranslation } from "react-i18next";
24	import innerText from "react-innertext";
25	
26	import { useTaskInstanceServiceGetLog } from "openapi/queries";
27	import type { TaskInstanceResponse, TaskInstancesLogResponse } from "openapi/requests/types.gen";
28	import { renderStructuredLog } from "src/components/renderStructuredLog";
29	import { isStatePending, useAutoRefresh } from "src/utils";
30	import { getTaskInstanceLink } from "src/utils/links";
31	import { parseStreamingLogContent } from "src/utils/logs";
32	
33	export type ParsedLogEntry = {
34	  element: JSX.Element | string | undefined;
35	  group?: { id: number; level: number; parentId?: number; type: "header" | "line" };
36	};
37	
38	type Props = {
39	  accept?: "*/*" | "application/json" | "application/x-ndjson";
40	  dagId: string;
41	  limit?: number;
42	  logLevelFilters?: Array<string>;
43	  showSource?: boolean;
44	  showTimestamp?: boolean;
45	  sourceFilters?: Array<string>;
46	  taskInstance?: TaskInstanceResponse;
47	  tryNumber?: number;
48	};
49	
50	type ParseLogsProps = {
51	  data: TaskInstancesLogResponse["content"];
52	  logLevelFilters?: Array<string>;
53	  showSource?: boolean;
54	  showTimestamp?: boolean;
55	  sourceFilters?: Array<string>;
56	  taskInstance?: TaskInstanceResponse;
57	  translate: TFunction;
58	  tryNumber: number;
59	};
60	
61	const parseLogs = ({
62	  data,
63	  logLevelFilters,
64	  showSource,
65	  showTimestamp,
66	  sourceFilters,
67	  taskInstance,
68	  translate,
69	  tryNumber,
70	}: ParseLogsProps) => {
71	  let warning;
72	  let parsedLines;
73	  const sources: Array<string> = [];
74	
75	  const logLink = taskInstance ? `${getTaskInstanceLink(taskInstance)}?try_number=${tryNumber}` : "";
76	
77	  try {
78	    let lineNumber = 0;
79	    const lineNumbers = data.map((datum) => {
80	      const text = typeof datum === "string" ? datum : datum.event;
81	
82	      if (text.includes("::group::") || text.includes("::endgroup::")) {
83	        return undefined;
84	      }
85	      const current = lineNumber;
86	
87	      lineNumber += 1;
88	
89	      return current;
90	    });
91	
92	    parsedLines = data
93	      .map((datum, index) => {
94	        if (typeof datum !== "string" && "logger" in datum) {
95	          const source = datum.logger as string;
96	
97	          if (!sources.includes(source)) {
98	            sources.push(source);
99	          }
100	        }
101	
102	        return renderStructuredLog({
103	          index: lineNumbers[index] ?? index,
104	          logLevelFilters,
105	          logLink,
106	          logMessage: datum,
107	          renderingMode: "jsx",
108	          showSource,
109	          showTimestamp,
110	          sourceFilters,
111	          translate,
112	        });
113	      })
114	      .filter((parsedLine) => parsedLine !== "");
115	  } catch (error) {
116	    const errorMessage = error instanceof Error ? error.message : "An error occurred.";
117	
118	    // eslint-disable-next-line no-console
119	    console.warn(`Error parsing logs: ${errorMessage}`);
120	    warning = "Unable to show logs. There was an error parsing logs.";
121	
122	    return { data, warning };
123	  }
124	
125	  const flatEntries: Array<ParsedLogEntry> = (() => {
126	    type Group = { id: number; level: number; name: string };
127	    const groupStack: Array<Group> = [];
128	    const result: Array<ParsedLogEntry> = [];
129	    let nextGroupId = 0;
130	
131	    parsedLines.forEach((line) => {
132	      const text = innerText(line);
133	
134	      if (text.includes("::group::")) {
135	        const groupName = text.split("::group::")[1] as string;
136	        const id = nextGroupId;
137	
138	        nextGroupId += 1;
139	        const level = groupStack.length;
140	        const parentGroup = groupStack[groupStack.length - 1];
141	
142	        groupStack.push({ id, level, name: groupName });
143	        result.push({
144	          element: groupName,
145	          group: { id, level, parentId: parentGroup?.id, type: "header" },
146	        });
147	
148	        return;
149	      }
150	
151	      if (text.includes("::endgroup::")) {
152	        groupStack.pop();
153	
154	        return;
155	      }
156	
157	      const currentGroup = groupStack[groupStack.length - 1];
158	
159	      if (groupStack.length > 0 && currentGroup) {
160	        result.push({
161	          element: line,
162	          group: { id: currentGroup.id, level: currentGroup.level, type: "line" },
163	        });
164	      } else {
165	        result.push({ element: line });
166	      }
167	    });
168	
169	    // Handle unclosed groups: their lines are already in result as flat entries
170	    return result;
171	  })();
172	
173	  return {
174	    parsedLogs: flatEntries,
175	    sources,
176	    warning,
177	  };
178	};
179	
180	// Log truncation is performed in the frontend because the backend
181	// does not support yet pagination / limits on logs reading endpoint
182	const truncateData = (data: TaskInstancesLogResponse | undefined, limit?: number) => {
183	  if (!data?.content || limit === undefined || limit <= 0) {
184	    return data;
185	  }
186	
187	  const streamingContent = parseStreamingLogContent(data);
188	  const truncatedContent =
189	    streamingContent.length > limit ? streamingContent.slice(-limit) : streamingContent;
190	
191	  return {
192	    ...data,
193	    content: truncatedContent,
194	  };
195	};
196	
197	export const useLogs = (
198	  {
199	    accept = "application/x-ndjson",
200	    dagId,
201	    limit,
202	    logLevelFilters,
203	    showSource,
204	    showTimestamp,
205	    sourceFilters,
206	    taskInstance,
207	    tryNumber = 1,
208	  }: Props,
209	  options?: Omit<UseQueryOptions<TaskInstancesLogResponse>, "queryFn" | "queryKey">,
210	) => {
211	  const { t: translate } = useTranslation("common");
212	  const refetchInterval = useAutoRefresh({ dagId });
213	
214	  const { data, ...rest } = useTaskInstanceServiceGetLog(
215	    {
216	      accept,
217	      dagId,
218	      dagRunId: taskInstance?.dag_run_id ?? "",
219	      mapIndex: taskInstance?.map_index ?? -1,
220	      taskId: taskInstance?.task_id ?? "",
221	      tryNumber,
222	    },
223	    undefined,
224	    {
225	      enabled: Boolean(taskInstance),
226	      refetchInterval: (query) =>
227	        isStatePending(taskInstance?.state) ||
228	        dayjs(query.state.dataUpdatedAt).isBefore(taskInstance?.end_date)
229	          ? refetchInterval
